import java.util.*;

class Solution {
    public TreeNode deleteNode(TreeNode root, int key) {
        if (root == null) return null; // key not found
        if (key < root.val) root.left = deleteNode(root.left, key);
        else if (key > root.val) root.right = deleteNode(root.right, key);
        else {
            if (root.left == null) return root.right;  // zero or one child
            if (root.right == null) return root.left;
            TreeNode s = root.right;                    // in-order successor
            while (s.left != null) s = s.left;
            root.val = s.val;                           // copy successor's value
            root.right = deleteNode(root.right, s.val); // remove the successor
        }
        return root;
    }
}

