function deleteNode(root, key) {
  let par = null, cur = root;
  while (cur && cur.val !== key) { par = cur; cur = key < cur.val ? cur.left : cur.right; }
  if (!cur) return root;
  let rep;
  if (!cur.left) rep = cur.right;
  else if (!cur.right) rep = cur.left;
  else {
    let sp = cur, s = cur.right;
    while (s.left) { sp = s; s = s.left; }
    cur.val = s.val;
    if (sp === cur) sp.right = s.right; else sp.left = s.right;
    return root;
  }
  if (!par) return rep;
  if (par.left === cur) par.left = rep; else par.right = rep;
  return root;
}
